from collections import defaultdict, deque

edges = [(7, 20), (12, 16), (20, 23), (3, 10), (3, 16), (14, 16), (5, 10), (5, 19), (17, 24), (11, 14), (19, 21), (9, 20), (8, 21), (11, 23), (1, 12), (15, 17), (6, 17), (4, 5), (20, 22), (14, 18), (0, 1), (14, 24), (9, 16), (0, 4), (2, 7), (10, 23), (1, 23), (6, 19), (7, 18), (3, 8), (22, 24), (4, 22), (10, 13), (9, 15), (2, 6), (2, 12), (11, 21), (13, 18), (0, 18), (13, 15), (7, 8)]

n = 25
adj = defaultdict(set)
for u, v in edges:
    adj[u].add(v)
    adj[v].add(u)

# Check degrees
degrees = [len(adj[i]) for i in range(n)]
print("Degrees:", degrees)
print("Min degree:", min(degrees))
print("Max degree:", max(degrees))
print("All degrees in [3,4]:", all(3 <= d <= 4 for d in degrees))

# Check girth using BFS from each vertex
def find_girth(adj, n):
    min_cycle = float('inf')
    for start in range(n):
        dist = {start: 0}
        parent = {start: -1}
        queue = deque([start])
        while queue:
            u = queue.popleft()
            for v in adj[u]:
                if v not in dist:
                    dist[v] = dist[u] + 1
                    parent[v] = u
                    queue.append(v)
                elif v != parent[u]:
                    cycle_len = dist[u] + dist[v] + 1
                    min_cycle = min(min_cycle, cycle_len)
    return min_cycle

girth = find_girth(adj, n)
print("Girth:", girth)
print("Girth >= 6:", girth >= 6)

# Also verify no cycles of length 3, 4, 5 explicitly
def find_all_short_cycles(adj, n, max_len):
    """Find all cycles of length <= max_len"""
    cycles = []
    for start in range(n):
        # BFS with path tracking
        queue = deque([(start, [start])])
        visited_paths = {(start,): True}
        while queue:
            u, path = queue.popleft()
            if len(path) > max_len:
                continue
            for v in adj[u]:
                if v == start and len(path) >= 3:
                    cycles.append(path + [v])
                elif v not in path and len(path) < max_len:
                    new_path = path + [v]
                    # Normalize to avoid duplicates
                    min_idx = new_path.index(min(new_path))
                    normalized = tuple(new_path[min_idx:] + new_path[:min_idx])
                    if normalized not in visited_paths:
                        visited_paths[normalized] = True
                        queue.append((v, new_path))
    return cycles

short_cycles = find_all_short_cycles(adj, n, 5)
print(f"Cycles of length 3-5: {len(short_cycles)}")
for c in short_cycles[:10]:
    print(f"  Cycle of length {len(c)-1}: {c}")
